import hashlib
import json
import random
from pathlib import Path

import pytest
from redline.beat import library, library_build
from redline.beat.library import LibraryError
from redline.cli import main

OWNER_REPO = "someone/samples"
COMMIT = "0123456789abcdef0123456789abcdef01234567"


def blob_sha1(data: bytes) -> str:
    return hashlib.sha1(b"blob %d\0" % len(data) + data).hexdigest()


def noise(seed: int, size: int = 2000) -> bytes:
    return random.Random(seed).randbytes(size)


class FakeOpener:
    """Serves generated bytes by URL, at most the limit asked for, and records every call."""

    def __init__(self, served: dict[str, bytes]):
        self.served = served
        self.calls: list[str] = []

    def __call__(self, url: str, limit: int) -> bytes:
        self.calls.append(url)
        return self.served[url][:limit]


def url(path: str) -> str:
    return library.raw_url(f"https://github.com/{OWNER_REPO}", COMMIT, path)


def write_manifest(tmp_path: Path, files: dict[str, tuple[bytes, int, list[int]]], **extra):
    entry = {
        "name": "test-bells",
        "source": f"https://github.com/{OWNER_REPO}",
        "commit": COMMIT,
        "licence": "CC0-1.0",
        "licence_quote": "CC0 1.0 Universal",
        "kind": "fetch",
        "commercial": True,
        "files": [
            {
                "path": path,
                "git_sha1": blob_sha1(data),
                "size": len(data),
                "note": note,
                "vel": vel,
            }
            for path, (data, note, vel) in files.items()
        ],
    }
    entry.update(extra)
    local = {
        "name": "hand-placed",
        "source": "https://example.org/samples",
        "licence": "custom",
        "licence_quote": "must not be sold",
        "kind": "local_only",
        "commercial": False,
        "note": "placed by hand into work/sounds/hand-placed/, never redistributed",
        "files": [],
    }
    manifest = tmp_path / "library.json"
    manifest.write_text(json.dumps({"sources": [entry, local]}), encoding="utf-8")
    return manifest


@pytest.fixture
def bells(tmp_path):
    files = {
        "Bells/Soft Set/bell_C3_soft.wav": (noise(1), 48, [0, 63]),
        "Bells/Soft Set/bell_C4_soft.wav": (noise(2), 60, [0, 63]),
        "Bells/Soft Set/bell_C5_soft.wav": (noise(3), 72, [0, 63]),
        "Bells/Loud, Set/bell_A#3_loud.wav": (noise(4), 58, [64, 127]),
        "Bells/Loud, Set/bell_C5_loud.wav": (noise(5), 72, [64, 127]),
    }
    manifest = write_manifest(tmp_path, files)
    opener = FakeOpener({url(path): data for path, (data, _, _) in files.items()})
    root = tmp_path / "sounds"
    return manifest, opener, root, files


def test_fetch_writes_verified_files(bells):
    manifest, opener, root, files = bells
    result = library.fetch("test-bells", root, opener=opener, manifest=manifest)
    assert sorted(result.downloaded) == sorted(files)
    assert result.present == ()
    for path, (data, _, _) in files.items():
        assert (root / "test-bells" / path).read_bytes() == data
    assert "Bells/Loud%2C%20Set/bell_A%233_loud.wav" in " ".join(opener.calls)
    assert all(
        call.startswith(f"https://raw.githubusercontent.com/{OWNER_REPO}/{COMMIT}/")
        for call in opener.calls
    )
    assert not list(root.rglob("*.part"))


@pytest.mark.parametrize("damage", ["hash", "longer", "shorter"])
def test_a_wrong_download_is_refused_and_nothing_is_written(tmp_path, damage):
    data = noise(7)
    manifest = write_manifest(tmp_path, {"one/bell_C4.wav": (data, 60, [0, 127])})
    served = {
        "hash": data[:-1] + bytes([data[-1] ^ 1]),
        "longer": data + b"x",
        "shorter": data[:-1],
    }[damage]
    opener = FakeOpener({url("one/bell_C4.wav"): served})
    root = tmp_path / "sounds"
    with pytest.raises(LibraryError, match=r"one/bell_C4\.wav"):
        library.fetch("test-bells", root, opener=opener, manifest=manifest)
    assert [p for p in root.rglob("*") if p.is_file()] == []


def test_a_failed_download_is_refused_and_nothing_is_written(tmp_path):
    manifest = write_manifest(tmp_path, {"one/bell_C4.wav": (noise(7), 60, [0, 127])})

    def offline(url: str, limit: int) -> bytes:
        raise TimeoutError("timed out")

    with pytest.raises(LibraryError, match="download failed"):
        library.fetch("test-bells", tmp_path / "sounds", opener=offline, manifest=manifest)
    assert not (tmp_path / "sounds" / "test-bells" / "one").exists()


@pytest.mark.parametrize("bad", ["../escape_C4.wav", "a/../../escape_C4.wav", "/etc/x_C4.wav"])
def test_a_path_leaving_the_folder_is_refused_before_any_download(tmp_path, bad):
    manifest = write_manifest(tmp_path, {bad: (noise(1), 60, [0, 127])})
    opener = FakeOpener({})
    with pytest.raises(LibraryError, match="path"):
        library.fetch("test-bells", tmp_path / "sounds", opener=opener, manifest=manifest)
    assert opener.calls == []
    assert not (tmp_path / "escape_C4.wav").exists()


def test_a_symlink_out_of_the_folder_is_refused(tmp_path):
    data = noise(1)
    manifest = write_manifest(tmp_path, {"sub/bell_C4.wav": (data, 60, [0, 127])})
    outside = tmp_path / "outside"
    outside.mkdir()
    folder = tmp_path / "sounds" / "test-bells"
    folder.mkdir(parents=True)
    (folder / "sub").symlink_to(outside, target_is_directory=True)
    opener = FakeOpener({url("sub/bell_C4.wav"): data})
    with pytest.raises(LibraryError, match="outside"):
        library.fetch("test-bells", tmp_path / "sounds", opener=opener, manifest=manifest)
    assert opener.calls == []
    assert list(outside.iterdir()) == []


def test_a_symlinked_file_pointing_outside_is_refused(tmp_path):
    data = noise(1)
    manifest = write_manifest(tmp_path, {"bell_C4.wav": (data, 60, [0, 127])})
    target = tmp_path / "elsewhere.wav"
    target.write_bytes(b"keep")
    folder = tmp_path / "sounds" / "test-bells"
    folder.mkdir(parents=True)
    (folder / "bell_C4.wav").symlink_to(target)
    with pytest.raises(LibraryError, match="outside"):
        library.fetch(
            "test-bells",
            tmp_path / "sounds",
            opener=FakeOpener({url("bell_C4.wav"): data}),
            manifest=manifest,
        )
    assert target.read_bytes() == b"keep"


def test_local_only_and_unknown_names_are_refused(bells):
    manifest, opener, root, _ = bells
    with pytest.raises(LibraryError, match="by hand"):
        library.fetch("hand-placed", root, opener=opener, manifest=manifest)
    with pytest.raises(LibraryError, match="no-such-sound"):
        library.fetch("no-such-sound", root, opener=opener, manifest=manifest)
    with pytest.raises(LibraryError, match="no-such-sound"):
        library.commercial("no-such-sound", manifest=manifest)
    assert opener.calls == []
    assert not root.exists()


def test_a_second_fetch_downloads_nothing(bells):
    manifest, opener, root, files = bells
    library.fetch("test-bells", root, opener=opener, manifest=manifest)
    opener.calls.clear()
    again = library.fetch("test-bells", root, opener=opener, manifest=manifest)
    assert opener.calls == []
    assert again.downloaded == ()
    assert sorted(again.present) == sorted(files)


def test_a_partial_fetch_is_completed_and_a_damaged_file_replaced(bells):
    manifest, opener, root, files = bells
    paths = sorted(files)
    folder = root / "test-bells"
    for path in paths[:2]:
        (folder / path).parent.mkdir(parents=True, exist_ok=True)
        (folder / path).write_bytes(files[path][0])
    damaged = paths[2]
    (folder / damaged).parent.mkdir(parents=True, exist_ok=True)
    (folder / damaged).write_bytes(b"cut short")
    result = library.fetch("test-bells", root, opener=opener, manifest=manifest)
    assert sorted(result.present) == paths[:2]
    assert sorted(result.downloaded) == paths[2:]
    assert sorted(opener.calls) == sorted(url(p) for p in paths[2:])
    assert (folder / damaged).read_bytes() == files[damaged][0]


def test_zones_pick_the_nearest_roots_of_each_layer(bells):
    manifest, opener, root, _ = bells
    library.fetch("test-bells", root, opener=opener, manifest=manifest)
    every = library.zones("test-bells", root, manifest=manifest)
    assert len(every) == 5
    assert all(zone.path.is_file() for zone in every)

    def picked(notes):
        found = library.zones("test-bells", root, notes_used=notes, manifest=manifest)
        return sorted((zone.vel, zone.note) for zone in found)

    assert picked([61]) == [((0, 63), 60), ((64, 127), 58)]
    assert picked([0]) == [((0, 63), 48), ((64, 127), 58)]
    assert picked([127]) == [((0, 63), 72), ((64, 127), 72)]
    assert picked([50, 70]) == [((0, 63), 48), ((0, 63), 72), ((64, 127), 58), ((64, 127), 72)]
    assert picked([]) == []


def test_zones_refuse_a_tampered_or_missing_file(bells):
    manifest, opener, root, _ = bells
    library.fetch("test-bells", root, opener=opener, manifest=manifest)
    tampered = root / "test-bells" / "Bells/Soft Set/bell_C4_soft.wav"
    data = bytearray(tampered.read_bytes())
    data[100] ^= 0xFF
    tampered.write_bytes(bytes(data))
    with pytest.raises(LibraryError, match="bell_C4_soft"):
        library.zones("test-bells", root, notes_used=[60], manifest=manifest)
    # an unused file is not read
    assert len(library.zones("test-bells", root, notes_used=[72], manifest=manifest)) == 2
    tampered.unlink()
    with pytest.raises(LibraryError, match="missing"):
        library.zones("test-bells", root, notes_used=[60], manifest=manifest)


def test_zones_refuse_a_local_only_source(bells):
    manifest, _, root, _ = bells
    with pytest.raises(LibraryError, match="by hand"):
        library.zones("hand-placed", root, manifest=manifest)


@pytest.mark.parametrize(
    ("change", "message"),
    [
        ({"licence": "CC-BY-4.0"}, "commercial"),
        ({"commit": "main"}, "commit"),
        ({"source": "https://example.org/x/y"}, "source"),
        ({"kind": "zip"}, "kind"),
        ({"name": "../up"}, "name"),
    ],
)
def test_a_bad_manifest_entry_is_refused(tmp_path, change, message):
    manifest = write_manifest(tmp_path, {"a_C4.wav": (noise(1), 60, [0, 127])}, **change)
    with pytest.raises(LibraryError, match=message):
        library.load(manifest)


@pytest.mark.parametrize(
    ("field", "value"),
    [("git_sha1", "abc"), ("size", 0), ("note", 128), ("vel", [64, 63]), ("vel", [0, 128])],
)
def test_a_bad_file_entry_is_refused(tmp_path, field, value):
    manifest = write_manifest(tmp_path, {"a_C4.wav": (noise(1), 60, [0, 127])})
    raw = json.loads(manifest.read_text(encoding="utf-8"))
    raw["sources"][0]["files"][0][field] = value
    manifest.write_text(json.dumps(raw), encoding="utf-8")
    with pytest.raises(LibraryError, match=field):
        library.load(manifest)


def test_a_local_only_entry_with_files_or_commercial_is_refused(tmp_path):
    manifest = write_manifest(tmp_path, {"a_C4.wav": (noise(1), 60, [0, 127])})
    raw = json.loads(manifest.read_text(encoding="utf-8"))
    raw["sources"][1]["commercial"] = True
    manifest.write_text(json.dumps(raw), encoding="utf-8")
    with pytest.raises(LibraryError, match="commercial"):
        library.load(manifest)
    raw["sources"][1]["commercial"] = False
    raw["sources"][1]["files"] = raw["sources"][0]["files"]
    manifest.write_text(json.dumps(raw), encoding="utf-8")
    with pytest.raises(LibraryError, match="files"):
        library.load(manifest)


def test_the_committed_manifest_validates():
    sources = library.load()
    fetched = [s for s in sources.values() if s.kind == "fetch"]
    local = [s for s in sources.values() if s.kind == "local_only"]
    assert 8 <= len(fetched) <= 10
    assert len(local) == 2
    for source in fetched:
        assert source.licence == "CC0-1.0"
        assert source.commercial is True
        assert library.commercial(source.name) is True
        assert sum(f.size for f in source.files) <= library_build.MAX_BYTES
        assert len({f.vel for f in source.files}) in (1, 2)
        for item in source.files:
            assert item.note == library_build.parse_note(item.path)
    for source in local:
        assert source.commercial is False
        assert library.commercial(source.name) is False
        assert source.files == ()
        assert "by hand" in source.note


