def tree(*paths_sizes: tuple[str, int]) -> dict:
    return {
        "truncated": False,
        "tree": [
            {"path": path, "type": "blob", "sha": f"{i:040x}", "size": size}
            for i, (path, size) in enumerate(paths_sizes, start=1)
        ]
        + [{"path": "Inst", "type": "tree", "sha": "f" * 40}],
    }


def test_build_takes_one_round_robin_per_note_and_layer():
    listing = tree(
        ("Inst/x_C4_soft_rr2.wav", 10),
        ("Inst/x_C4_soft_rr1.wav", 10),
        ("Inst/x_C4_loud_rr1.wav", 10),
        ("Inst/x_E4_loud_rr1.wav", 10),
        ("Inst/x_E4_med_rr1.wav", 10),
        ("Inst/loose_000_med.wav", 10),
        ("Inst/notes.txt", 10),
        ("Inst/Deeper/x_G4_loud_rr1.wav", 10),
        ("Other/x_C4_soft_rr1.wav", 10),
    )
    pick = library_build.Pick("t-inst", "repo", "Inst", (("soft",), ("loud",)))
    files = library_build.pick_files(listing, pick)
    assert [(f["path"], f["note"], f["vel"]) for f in files] == [
        ("Inst/x_C4_soft_rr1.wav", 60, [0, 63]),
        ("Inst/x_C4_loud_rr1.wav", 60, [64, 127]),
        ("Inst/x_E4_loud_rr1.wav", 64, [64, 127]),
    ]
    assert files[0]["git_sha1"] == f"{2:040x}" and files[0]["size"] == 10


def test_build_keeps_the_note_range_and_refuses_an_entry_over_budget():
    listing = tree(("Inst/x_C1.wav", 5), ("Inst/x_C4.wav", 5), ("Inst/x_C8.wav", 5))
    ranged = library_build.Pick("t", "repo", "Inst", ((),), low=24, high=96)
    assert [f["note"] for f in library_build.pick_files(listing, ranged)] == [24, 60]
    big = tree(("Inst/x_C4.wav", library_build.MAX_BYTES + 1))
    with pytest.raises(LibraryError, match="budget"):
        library_build.pick_files(big, library_build.Pick("t", "repo", "Inst", ((),)))
    with pytest.raises(LibraryError, match="layer"):
        library_build.Pick("t", "repo", "Inst", ((), (), ()))
    with pytest.raises(LibraryError, match="no file"):
        library_build.pick_files(listing, library_build.Pick("t", "repo", "Inst", (("ff",),)))
    with pytest.raises(LibraryError, match="truncated"):
        library_build.pick_files({"truncated": True, "tree": []}, ranged)


def test_cli_lists_and_fetches(bells, monkeypatch, capsys, tmp_path):
    manifest, opener, _, files = bells
    monkeypatch.setattr(library, "MANIFEST", manifest)
    monkeypatch.setattr(library, "download", opener)
    work = tmp_path / "work"
    assert main(["beat", "sounds", "list", "--work", str(work)]) == 0
    listed = capsys.readouterr().out
    assert "test-bells" in listed and "not fetched" in listed and "by hand" in listed
    assert main(["beat", "sounds", "fetch", "test-bells", "--work", str(work)]) == 0
    assert (work / "sounds" / "test-bells" / sorted(files)[0]).is_file()
    capsys.readouterr()
    assert main(["beat", "sounds", "list", "--work", str(work)]) == 0
    line = capsys.readouterr().out.split("test-bells")[1].splitlines()[0]
    assert "fetched" in line and "not fetched" not in line
    assert main(["beat", "sounds", "fetch", "hand-placed", "--work", str(work)]) == 2
    assert "by hand" in capsys.readouterr().err
